-- Exact live source: migrations/snapshots/comment-like-after-v410/before.json.
-- Only 2 Like blocks, 4 seeding workflows and 1 new element; preserve comment blocks/UI labels.
-- DML only: no RPC, schema reload, connection source or historical campaign changes.
BEGIN;
SET LOCAL timezone='UTC';
SET LOCAL lock_timeout='2s';
SET LOCAL statement_timeout='8s';
SELECT id FROM public.auto_blocks WHERE id IN(34,2074,2614,2615,2616) ORDER BY id FOR UPDATE;
SELECT id FROM public.auto_elements WHERE id IN(1456,1517,1784) ORDER BY id FOR UPDATE;
SELECT id FROM public.auto_workflows WHERE id IN(1,2,157,207,226,238,244,245) ORDER BY id FOR UPDATE;
DO $v410$
BEGIN
IF EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE name LIKE 'migration_v410_%') THEN RAISE EXCEPTION 'v410 already applied'; END IF;
IF EXISTS(SELECT 1 FROM public.auto_elements WHERE name='fb_comment_post_like_button') THEN RAISE EXCEPTION 'v410 element already exists'; END IF;
IF (SELECT jsonb_agg(jsonb_build_object(
  'workflow_id', w.id, 'node_id', n->>'id', 'block_id', n->>'blockId',
  'override', n->'codeOverride') ORDER BY w.id, n->>'id')
  FROM public.auto_workflows w CROSS JOIN LATERAL jsonb_array_elements(w.nodes) n
  WHERE n->>'blockId' IN ('2074','2615')) IS DISTINCT FROM '[{"block_id":"2074","node_id":"like_at_pos","override":null,"workflow_id":157},{"block_id":"2615","node_id":"like_current_post","override":null,"workflow_id":207},{"block_id":"2615","node_id":"like_current_post","override":null,"workflow_id":244},{"block_id":"2074","node_id":"like_at_pos","override":null,"workflow_id":245}]'::jsonb THEN RAISE EXCEPTION 'v410 Like consumers drift'; END IF;
IF (SELECT md5(to_jsonb(t)::text) FROM public.auto_blocks t WHERE id=34) IS DISTINCT FROM '02d02cde892483bd98370584e0d3ca08' THEN RAISE EXCEPTION 'v410: auto_blocks/34 drift'; END IF;
IF (SELECT md5(to_jsonb(t)::text) FROM public.auto_blocks t WHERE id=2074) IS DISTINCT FROM 'c2710e14d1c7af9161ae0e344b7707f9' THEN RAISE EXCEPTION 'v410: auto_blocks/2074 drift'; END IF;
