IF (SELECT md5(to_jsonb(t)::text) FROM public.auto_workflows t WHERE id=1) IS DISTINCT FROM 'bd87d312f3a64de77376387dd31e4c06' THEN RAISE EXCEPTION 'v410: auto_workflows/1 drift'; END IF;
IF (SELECT md5(to_jsonb(t)::text) FROM public.auto_workflows t WHERE id=2) IS DISTINCT FROM 'a98c0675b4c0b7b5b1772d5497f547c9' THEN RAISE EXCEPTION 'v410: auto_workflows/2 drift'; END IF;
IF (SELECT md5(to_jsonb(t)::text) FROM public.auto_workflows t WHERE id=157) IS DISTINCT FROM 'c71addb507fc158e3da0ff73a1877656' THEN RAISE EXCEPTION 'v410: auto_workflows/157 drift'; END IF;
IF (SELECT md5(to_jsonb(t)::text) FROM public.auto_workflows t WHERE id=207) IS DISTINCT FROM '0bf510a8374bc4f1758413decdc99513' THEN RAISE EXCEPTION 'v410: auto_workflows/207 drift'; END IF;
